with w as(select * from public.works where id=816) select jsonb_build_object('checked_at',clock_timestamp(),'works',(select jsonb_agg(to_jsonb(w) order by id) from w),'authors',(select jsonb_agg(to_jsonb(a) order by id) from public.authors a where id in(select author_id from w)),'editions',(select jsonb_agg(to_jsonb(e) order by id) from public.editions e where work_id in(select id from w) or isbn_13='9789000365043' or open_library_edition_id='OL46531174M'),'descriptions',(select coalesce(jsonb_agg(to_jsonb(d) order by work_id,language),'[]') from public.catalog_work_descriptions d where work_id in(select id from w)),'metadata',(select coalesce(jsonb_agg(to_jsonb(m) order by edition_id),'[]') from public.catalog_edition_metadata m where work_id in(select id from w))) as preflight;
